    public void showArray(){
        if(!debug)
            return;
        System.out.println("Classes are : ");
        for(int i=0; i<className.size(); i++)
            System.out.print(className.get(i)+" ");
        System.out.println("");
    }

    private ArrayList<Integer> makeIDVector(){
        ArrayList<Integer> par = new ArrayList<>();
        for(int i=0; i<parent.size(); i++){
           if(parent.get(i)==null){
               par.add(null);
               continue;
           }
           if(!classID.containsKey(parent.get(i)))
                (new ErrorFunc()).throwSymbolError(parent.get(i)+"ClassError");
           par.add(classID.get(parent.get(i)));
        }
        if(debug && graphDebug){
            for(int i=0; i<par.size(); i++){
                if(par.get(i)==null)
                    continue;
                System.out.println("Parent of "+className.get(i)+" is "+className.get(par.get(i)));
            }
        }
        return par;
    }

    public ArrayList<TreeNode> createGraph(){
        ArrayList<ArrayList<Node>> graph = new ArrayList<>();

        // Get the ID -> parentID vector
        ArrayList<Integer> parentID = makeIDVector();

        // Now make adjacency list
        ArrayList<ArrayList<Integer>> adjList = new ArrayList<>();
        for(int i=0; i<parentID.size(); i++)
            adjList.add(new ArrayList<Integer>());
        for(int i=0; i<parentID.size(); i++)
            if(parentID.get(i)!=null){
                adjList.get(parentID.get(i)).add(i);
                if(parentID.get(i)==i)
                    (new ErrorFunc()).throwTypeError("Class extends itself");
            }
            

        // DEBUG print the graph
        if(debug && graphDebug){
            for(int i=0; i<adjList.size(); i++){
                System.out.print("Derived from Class "+className.get(i)+": ");
                for(int j=0; j<adjList.get(i).size(); j++){
                    System.out.print(className.get(adjList.get(i).get(j))+" ");
                }
                System.out.println("");
            }
        }

        // Make the trees using the adjLists
        ArrayList<TreeNode> forest = new ArrayList<>();
         // create a TreeNode for each class
        ArrayList<TreeNode> classTreeNode = new ArrayList<>();
        for(int i=0; i<classNode.size(); i++)
            classTreeNode.add(new TreeNode(classNode.get(i)));
         // Populate their children
        for(int i=0; i<classNode.size(); i++)
            for(int j=0; j<adjList.get(i).size(); j++)
                classTreeNode.get(i).addChild(classTreeNode.get(adjList.get(i).get(j)));
         // Add roots to forest
        for(int i=0; i<parent.size(); i++)
            if(parent.get(i)==null)
                forest.add(classTreeNode.get(i));

        return forest;
    }

