    public boolean isParent(String par, String ch){
       if(ch==par)
           return true;
       String cur = ch;
       int curIndex = -1;
       if(!classID.containsKey(ch))
           return false;
       curIndex = classID.get(ch);
       while(parent.get(curIndex)!=null){
           if(debug){
                System.out.println(par);
                System.out.flush();
           }
            cur = parent.get(curIndex);
            if(cur==par)
                return true;
            if(!classID.containsKey(cur))
                return false;
            curIndex = classID.get(cur);
       }
       return false;
    }

